private bool IsTeacherWorkWithExtraDescription(int teacherWorkId)
{
    return teacherWorkId == 34 || teacherWorkId == 35;
}

private bool IsTeacherWorkWithExtraDescription(object teacherWorkId)
{
    if (teacherWorkId == null || teacherWorkId == DBNull.Value)
        return false;

    return IsTeacherWorkWithExtraDescription(Convert.ToInt32(teacherWorkId));
}

protected bool ShowExtraDescriptionColumns
{
    get
    {
        if (ViewState["ShowExtraDescriptionColumns"] != null)
            return Convert.ToBoolean(ViewState["ShowExtraDescriptionColumns"]);
        return false;
    }
    set { ViewState["ShowExtraDescriptionColumns"] = value; }
}

private void UpdateShowExtraDescriptionColumns()
{
    bool show = false;

    if (ddlTeacherWorkID.SelectedValue != null && ddlTeacherWorkID.SelectedValue != "")
    {
        int teacherWorkId = Convert.ToInt32(ddlTeacherWorkID.SelectedValue);
        if (IsTeacherWorkWithExtraDescription(teacherWorkId))
            show = true;
    }

    if (!show && dtbData != null)
    {
        foreach (DataRow row in dtbData.Rows)
        {
            if (IsTeacherWorkWithExtraDescription(row["TeacherWorkID"]))
            {
                show = true;
                break;
            }
        }
    }

    ShowExtraDescriptionColumns = show;
}

protected string GetExtraDescriptionColumnStyle()
{
    return ShowExtraDescriptionColumns ? "" : "display:none";
}

private void LoadData(string sortExpression = null)

dtbData.DefaultView.Sort = sortExpression;
UpdateShowExtraDescriptionColumns();
rptList.DataSource = dtbData;
rptList.DataBind();

