protected void rptList_ItemDataBound(object sender, RepeaterItemEventArgs e)
{
    if (e.Item.ItemIndex >= 0)
    {
        // tạo sự kiện khi click vào duyệt 1 thì đánh dấu vào txt duyệt để khi chạy for save cho nhanh
        TextBox txtFlag = e.Item.FindControl("txtFlag") as TextBox;
        Telerik.Web.UI.RadNumericTextBox txtRequestQuantity = e.Item.FindControl("txtRequestQuantity") as Telerik.Web.UI.RadNumericTextBox;
        TextBox txtDesc = e.Item.FindControl("txtDescription") as TextBox;
        TextBox txtDesc1 = e.Item.FindControl("txtDescription1") as TextBox;
        TextBox txtDesc2 = e.Item.FindControl("txtDescription2") as TextBox;
        TextBox txtDesc3 = e.Item.FindControl("txtDescription3") as TextBox;
        TextBox txtDesc4 = e.Item.FindControl("txtDescription4") as TextBox;
        HiddenField hidTeacherWorkID = e.Item.FindControl("hidTeacherWorkID") as HiddenField;

        txtRequestQuantity.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);
        txtDesc.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);

        if (ShowExtraDescriptionColumns && hidTeacherWorkID != null)
        {
            int teacherWorkId = Convert.ToInt32(hidTeacherWorkID.Value.Trim());
            bool showExtraFields = IsTeacherWorkWithExtraDescription(teacherWorkId);

            txtDesc1.Visible = showExtraFields;
            txtDesc2.Visible = showExtraFields;
            txtDesc3.Visible = showExtraFields;
            txtDesc4.Visible = showExtraFields;

            if (showExtraFields)
            {
                txtDesc1.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);
                txtDesc2.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);
                txtDesc3.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);
                txtDesc4.Attributes["onchange"] = string.Format("document.getElementById('{0}').value = '1';", txtFlag.ClientID);
            }
        }
    }
}

